-- Task 9 Fire Alarm pilot completion. Phase 1 tables remain authoritative.
CREATE TABLE `product_versions` (`id` text PRIMARY KEY NOT NULL, `product_id` text NOT NULL, `version_number` integer NOT NULL, `previous_version_id` text, `effective_from` text, `effective_to` text, `values_json` text NOT NULL, `source_id` text, `confidence` integer, `review_status` text NOT NULL DEFAULT 'Needs Review', `created_by` text NOT NULL, `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP, `superseded_at` text, `deleted_at` text, FOREIGN KEY (`product_id`) REFERENCES `library_products`(`id`), FOREIGN KEY (`source_id`) REFERENCES `product_sources`(`id`));
CREATE UNIQUE INDEX `product_versions_identity_idx` ON `product_versions` (`product_id`,`version_number`);
CREATE TABLE `product_variants` (`id` text PRIMARY KEY NOT NULL, `base_product_id` text NOT NULL, `variant_type` text NOT NULL, `variant_key` text NOT NULL, `values_json` text NOT NULL, `source_id` text, `evidence_json` text NOT NULL, `review_status` text NOT NULL DEFAULT 'Needs Review', `version_number` integer NOT NULL DEFAULT 1, `created_by` text NOT NULL, `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP, `superseded_at` text, `deleted_at` text, FOREIGN KEY (`base_product_id`) REFERENCES `library_products`(`id`));
CREATE UNIQUE INDEX `product_variants_key_idx` ON `product_variants` (`base_product_id`,`variant_type`,`variant_key`,`version_number`);
CREATE TABLE `product_aliases` (`id` text PRIMARY KEY NOT NULL, `product_id` text NOT NULL, `alias` text NOT NULL, `normalized_alias` text NOT NULL, `alias_type` text NOT NULL, `region` text, `source_id` text, `evidence_json` text NOT NULL, `review_status` text NOT NULL DEFAULT 'Needs Review', `created_by` text NOT NULL, `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP, `deleted_at` text, FOREIGN KEY (`product_id`) REFERENCES `library_products`(`id`));
CREATE INDEX `product_aliases_search_idx` ON `product_aliases` (`normalized_alias`,`review_status`);
CREATE TABLE `regional_part_numbers` (`id` text PRIMARY KEY NOT NULL, `product_id` text NOT NULL, `region` text NOT NULL, `part_number` text NOT NULL, `normalized_part_number` text NOT NULL, `source_id` text, `evidence_json` text NOT NULL, `review_status` text NOT NULL DEFAULT 'Needs Review', `created_by` text NOT NULL, `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP, `deleted_at` text, FOREIGN KEY (`product_id`) REFERENCES `library_products`(`id`));
CREATE UNIQUE INDEX `regional_part_numbers_identity_idx` ON `regional_part_numbers` (`region`,`normalized_part_number`);
CREATE TABLE `product_attributes` (`id` text PRIMARY KEY NOT NULL, `product_id` text NOT NULL, `variant_id` text, `attribute_definition_id` text, `attribute_name` text NOT NULL, `value_json` text, `original_value` text, `normalized_value` text, `unit` text, `source_id` text, `evidence_json` text NOT NULL, `confidence` integer NOT NULL DEFAULT 0, `review_status` text NOT NULL DEFAULT 'Needs Review', `version_number` integer NOT NULL DEFAULT 1, `created_by` text NOT NULL, `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP, `superseded_at` text, `deleted_at` text, FOREIGN KEY (`product_id`) REFERENCES `library_products`(`id`));
CREATE INDEX `product_attributes_search_idx` ON `product_attributes` (`attribute_name`,`normalized_value`,`unit`,`review_status`);
CREATE TABLE `product_certifications` (`id` text PRIMARY KEY NOT NULL, `product_id` text NOT NULL, `variant_id` text, `certification_type` text NOT NULL, `standard_body` text NOT NULL, `standard_number` text NOT NULL, `part` text, `revision_year` text, `scope` text, `region` text, `document_id` text, `evidence_location` text, `status` text NOT NULL DEFAULT 'Unverified', `confidence` integer NOT NULL DEFAULT 0, `review_status` text NOT NULL DEFAULT 'Needs Review', `version_number` integer NOT NULL DEFAULT 1, `created_by` text NOT NULL, `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP, `superseded_at` text, `deleted_at` text, FOREIGN KEY (`product_id`) REFERENCES `library_products`(`id`));
CREATE INDEX `product_certifications_search_idx` ON `product_certifications` (`standard_body`,`standard_number`,`part`,`region`,`status`);
CREATE TABLE `product_compatibility` (`id` text PRIMARY KEY NOT NULL, `source_product_id` text NOT NULL, `target_product_id` text, `target_family_id` text, `relationship_type` text NOT NULL, `conditions_json` text NOT NULL, `exceptions_json` text NOT NULL, `required_firmware` text, `required_protocol` text, `source_id` text, `evidence_json` text NOT NULL, `confidence` integer NOT NULL DEFAULT 0, `review_status` text NOT NULL DEFAULT 'Needs Review', `version_number` integer NOT NULL DEFAULT 1, `effective_from` text, `effective_to` text, `created_by` text NOT NULL, `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP, `superseded_at` text, `deleted_at` text, FOREIGN KEY (`source_product_id`) REFERENCES `library_products`(`id`));
CREATE INDEX `product_compatibility_source_idx` ON `product_compatibility` (`source_product_id`,`relationship_type`,`review_status`);
CREATE TABLE `product_accessories` (`id` text PRIMARY KEY NOT NULL, `product_id` text NOT NULL, `accessory_product_id` text NOT NULL, `relationship_type` text NOT NULL, `quantity_rule` text NOT NULL, `quantity_parameter` integer, `scope` text, `condition_json` text NOT NULL, `included` integer NOT NULL DEFAULT 0, `separately_priced` integer NOT NULL DEFAULT 1, `source_id` text, `evidence_json` text NOT NULL, `confidence` integer NOT NULL DEFAULT 0, `review_status` text NOT NULL DEFAULT 'Needs Review', `version_number` integer NOT NULL DEFAULT 1, `created_by` text NOT NULL, `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP, `superseded_at` text, `deleted_at` text, FOREIGN KEY (`product_id`) REFERENCES `library_products`(`id`), FOREIGN KEY (`accessory_product_id`) REFERENCES `library_products`(`id`));
CREATE INDEX `product_accessories_product_idx` ON `product_accessories` (`product_id`,`relationship_type`,`review_status`);
CREATE TABLE `product_packages` (`id` text PRIMARY KEY NOT NULL, `product_id` text NOT NULL, `package_code` text NOT NULL, `name` text NOT NULL, `source_id` text, `review_status` text NOT NULL DEFAULT 'Needs Review', `version_number` integer NOT NULL DEFAULT 1, `created_by` text NOT NULL, `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP, `superseded_at` text, `deleted_at` text, FOREIGN KEY (`product_id`) REFERENCES `library_products`(`id`));
CREATE TABLE `product_package_components` (`id` text PRIMARY KEY NOT NULL, `package_id` text NOT NULL, `component_product_id` text NOT NULL, `quantity_rule` text NOT NULL, `quantity` integer, `included` integer NOT NULL DEFAULT 1, `source_id` text, `evidence_json` text NOT NULL, `review_status` text NOT NULL DEFAULT 'Needs Review', FOREIGN KEY (`package_id`) REFERENCES `product_packages`(`id`), FOREIGN KEY (`component_product_id`) REFERENCES `library_products`(`id`));
CREATE TABLE `product_documents` (`id` text PRIMARY KEY NOT NULL, `product_id` text NOT NULL, `variant_id` text, `document_id` text NOT NULL, `document_version_id` text NOT NULL, `document_type` text NOT NULL, `source_location` text NOT NULL, `source_reliability` text NOT NULL, `review_status` text NOT NULL DEFAULT 'Needs Review', `created_by` text NOT NULL, `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP, `deleted_at` text, FOREIGN KEY (`product_id`) REFERENCES `library_products`(`id`));
CREATE INDEX `product_documents_product_idx` ON `product_documents` (`product_id`,`document_type`,`review_status`);
CREATE TABLE `product_identity_decisions` (`id` text PRIMARY KEY NOT NULL, `left_product_id` text NOT NULL, `right_product_id` text NOT NULL, `relationship_type` text NOT NULL, `action` text NOT NULL, `reason` text NOT NULL, `evidence_json` text NOT NULL, `reversal_of_id` text, `decided_by` text NOT NULL, `decided_role` text NOT NULL, `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE `product_conflicts` (`id` text PRIMARY KEY NOT NULL, `product_id` text, `conflict_type` text NOT NULL, `left_value` text NOT NULL, `right_value` text NOT NULL, `source_ids` text NOT NULL, `status` text NOT NULL DEFAULT 'Open', `resolution` text, `resolved_by` text, `resolved_at` text, `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP, `deleted_at` text);
CREATE TABLE `supplier_branches` (`id` text PRIMARY KEY NOT NULL, `supplier_id` text NOT NULL, `name` text NOT NULL, `region` text, `address_json` text NOT NULL, `status` text NOT NULL DEFAULT 'Active', `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP, `deleted_at` text, FOREIGN KEY (`supplier_id`) REFERENCES `suppliers`(`id`));
CREATE TABLE `supplier_contacts` (`id` text PRIMARY KEY NOT NULL, `supplier_id` text NOT NULL, `branch_id` text, `name` text NOT NULL, `role` text, `email` text, `phone` text, `status` text NOT NULL DEFAULT 'Active', `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP, `deleted_at` text, FOREIGN KEY (`supplier_id`) REFERENCES `suppliers`(`id`));
CREATE TABLE `supplier_products` (`id` text PRIMARY KEY NOT NULL, `supplier_id` text NOT NULL, `product_id` text, `supplier_product_code` text NOT NULL, `manufacturer_part_number` text, `mapping_confidence` integer NOT NULL DEFAULT 0, `review_status` text NOT NULL DEFAULT 'Needs Review', `source_id` text, `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP, `deleted_at` text, FOREIGN KEY (`supplier_id`) REFERENCES `suppliers`(`id`), FOREIGN KEY (`product_id`) REFERENCES `library_products`(`id`));
CREATE TABLE `supplier_quotes` (`id` text PRIMARY KEY NOT NULL, `supplier_id` text NOT NULL, `project_id` text, `quote_number` text NOT NULL, `quote_version` integer NOT NULL DEFAULT 1, `quote_date` text NOT NULL, `valid_until` text, `currency` text NOT NULL, `delivery_terms` text, `payment_terms` text, `warranty_terms` text, `source_document_id` text NOT NULL, `review_status` text NOT NULL DEFAULT 'Needs Review', `created_by` text NOT NULL, `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP, `superseded_at` text, `deleted_at` text, FOREIGN KEY (`supplier_id`) REFERENCES `suppliers`(`id`), FOREIGN KEY (`project_id`) REFERENCES `projects`(`id`));
CREATE UNIQUE INDEX `supplier_quotes_version_idx` ON `supplier_quotes` (`supplier_id`,`quote_number`,`quote_version`);
CREATE TABLE `supplier_quote_lines` (`id` text PRIMARY KEY NOT NULL, `supplier_quote_id` text NOT NULL, `line_number` integer NOT NULL, `product_id` text, `supplier_product_code` text, `manufacturer` text, `part_number` text, `description` text NOT NULL, `quantity` text, `unit_price_minor` integer, `discount_basis_points` integer, `net_price_minor` integer, `currency` text NOT NULL, `availability` text, `delivery` text, `source_location` text NOT NULL, `mapping_confidence` integer NOT NULL DEFAULT 0, `review_status` text NOT NULL DEFAULT 'Needs Review', `original_values` text NOT NULL, `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (`supplier_quote_id`) REFERENCES `supplier_quotes`(`id`), FOREIGN KEY (`product_id`) REFERENCES `library_products`(`id`));
CREATE UNIQUE INDEX `supplier_quote_lines_identity_idx` ON `supplier_quote_lines` (`supplier_quote_id`,`line_number`);
CREATE TABLE `price_source_versions` (`id` text PRIMARY KEY NOT NULL, `source_id` text NOT NULL, `version_number` integer NOT NULL, `previous_version_id` text, `source_type` text NOT NULL, `manufacturer_id` text, `supplier_id` text, `currency` text, `effective_from` text, `effective_to` text, `project_id` text, `region` text, `quantity_range` text, `reliability` text NOT NULL, `approval_state` text NOT NULL DEFAULT 'Needs Review', `downstream_use` text NOT NULL DEFAULT 'Discovery Only', `document_id` text NOT NULL, `document_version_id` text NOT NULL, `input_fingerprint` text NOT NULL, `uploaded_by` text NOT NULL, `approved_by` text, `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP, `superseded_at` text, FOREIGN KEY (`source_id`) REFERENCES `product_sources`(`id`));
CREATE UNIQUE INDEX `price_source_versions_idx` ON `price_source_versions` (`source_id`,`version_number`);
CREATE TABLE `price_record_versions` (`id` text PRIMARY KEY NOT NULL, `price_record_id` text NOT NULL, `version_number` integer NOT NULL, `previous_version_id` text, `values_json` text NOT NULL, `review_status` text NOT NULL DEFAULT 'Needs Review', `created_by` text NOT NULL, `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP, `superseded_at` text, FOREIGN KEY (`price_record_id`) REFERENCES `price_records`(`id`));
CREATE UNIQUE INDEX `price_record_versions_idx` ON `price_record_versions` (`price_record_id`,`version_number`);
CREATE TABLE `discount_rules` (`id` text PRIMARY KEY NOT NULL, `manufacturer_id` text NOT NULL, `source_id` text NOT NULL, `source_version_id` text NOT NULL, `family_scope` text NOT NULL, `component_scope` text NOT NULL, `discount_basis_points` integer NOT NULL, `calculation_method` text NOT NULL, `calculation_order` integer NOT NULL, `effective_from` text, `effective_to` text, `project_id` text, `approval_state` text NOT NULL DEFAULT 'Needs Review', `evidence_json` text NOT NULL, `version_number` integer NOT NULL DEFAULT 1, `created_by` text NOT NULL, `approved_by` text, `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP, `superseded_at` text);
CREATE TABLE `commercial_conditions` (`id` text PRIMARY KEY NOT NULL, `source_version_id` text NOT NULL, `condition_type` text NOT NULL, `value_json` text NOT NULL, `scope_json` text NOT NULL, `review_status` text NOT NULL DEFAULT 'Needs Review', `created_by` text NOT NULL, `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE `price_conflicts` (`id` text PRIMARY KEY NOT NULL, `product_id` text NOT NULL, `price_record_ids` text NOT NULL, `conflict_type` text NOT NULL, `status` text NOT NULL DEFAULT 'Open', `resolution` text, `resolved_by` text, `resolved_at` text, `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE `library_processing_jobs` (`id` text PRIMARY KEY NOT NULL, `source_id` text, `kind` text NOT NULL, `stage` text NOT NULL, `status` text NOT NULL, `progress` integer NOT NULL DEFAULT 0, `attempt` integer NOT NULL DEFAULT 0, `max_attempts` integer NOT NULL DEFAULT 3, `timeout_ms` integer NOT NULL, `cancel_requested` integer NOT NULL DEFAULT 0, `parser_version` text NOT NULL, `model_version` text NOT NULL, `prompt_version` text NOT NULL, `rule_version` text NOT NULL, `input_fingerprint` text NOT NULL, `idempotency_key` text NOT NULL, `logs_json` text NOT NULL DEFAULT '[]', `error_json` text, `created_by` text NOT NULL, `created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP, `started_at` text, `completed_at` text, `updated_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX `library_processing_idempotency_idx` ON `library_processing_jobs` (`kind`,`idempotency_key`);
